namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious traditional Neapolitan pizza.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 54
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, and pancetta.",
                Ingredients = ["400g spaghetti", "200g pancetta", "4 egg yolks", "100g Pecorino Romano", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk egg yolks with grated Pecorino and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with pancetta off the heat.", "Add egg mixture, tossing quickly. Add pasta water if needed."],
                TotalRatings = 8, RatingSum = 38
            },
            new()
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["500g chicken breast", "1 cup yogurt", "2 tbsp tikka masala paste", "400g canned tomatoes", "1 cup heavy cream", "Basmati rice"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onions, garlic, and ginger in a pan.", "Add tomatoes and tikka paste, simmer 15 min.", "Stir in cream and add chicken pieces.", "Serve over basmati rice with naan bread."],
                TotalRatings = 15, RatingSum = 70
            },
            new()
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Description = "Sweet, sour, and savory Thai stir-fried noodles.",
                Ingredients = ["200g rice noodles", "2 eggs", "Bean sprouts", "Crushed peanuts", "3 tbsp pad thai sauce", "Lime wedges"],
                Steps = ["Soak rice noodles in warm water for 30 min.", "Scramble eggs in a hot wok.", "Add drained noodles and pad thai sauce.", "Toss in bean sprouts and stir-fry 2 min.", "Garnish with crushed peanuts and lime.", "Serve immediately while hot."],
                TotalRatings = 6, RatingSum = 26
            },
            new()
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crispy tortillas with fresh toppings.",
                Ingredients = ["500g ground beef", "Taco seasoning", "Corn tortillas", "Shredded lettuce", "Diced tomatoes", "Sour cream and cheese"],
                Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 min.", "Warm tortillas in a dry pan.", "Fill tortillas with seasoned beef.", "Top with lettuce, tomatoes, cheese, and sour cream.", "Serve with salsa and lime wedges."],
                TotalRatings = 10, RatingSum = 43
            },
            new()
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich chocolate cake with a molten center.",
                Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour", "Powdered sugar for dusting"],
                Steps = ["Preheat oven to 425°F (220°C).", "Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold chocolate mixture into eggs, then add flour.", "Pour into greased ramekins.", "Bake 12-14 min. Center should be soft. Invert onto plates."],
                TotalRatings = 20, RatingSum = 95
            },
            new()
            {
                Id = 7, Title = "Caesar Salad", Category = "Salads",
                Description = "Crisp romaine with creamy Caesar dressing and croutons.",
                Ingredients = ["1 head romaine lettuce", "Caesar dressing", "Parmesan cheese", "Croutons", "Lemon juice", "Anchovy fillets (optional)"],
                Steps = ["Wash and chop romaine into bite-sized pieces.", "Toss lettuce with Caesar dressing.", "Shave Parmesan over the top.", "Add croutons and toss gently.", "Squeeze fresh lemon juice on top.", "Serve immediately as a side or add grilled chicken."],
                TotalRatings = 5, RatingSum = 21
            },
            new()
            {
                Id = 8, Title = "Miso Ramen", Category = "Asian",
                Description = "Hearty Japanese noodle soup with umami-rich miso broth.",
                Ingredients = ["Ramen noodles", "4 cups chicken broth", "3 tbsp white miso paste", "Soft-boiled eggs", "Corn kernels", "Sliced green onions"],
                Steps = ["Bring broth to a simmer.", "Dissolve miso paste into the broth.", "Cook ramen noodles according to package.", "Divide noodles into bowls and ladle broth over.", "Top with halved soft-boiled eggs and corn.", "Garnish with green onions and sesame seeds."],
                TotalRatings = 9, RatingSum = 40
            },
        ];
    }

    public List<RecipeCategory> GetCategories()
    {
        return
        [
            new() { Name = "Italian", Icon = "🍝", Description = "Pasta, pizza, and Mediterranean classics" },
            new() { Name = "Indian", Icon = "🍛", Description = "Rich curries and aromatic spices" },
            new() { Name = "Asian", Icon = "🍜", Description = "Stir-fries, noodles, and bold flavors" },
            new() { Name = "Mexican", Icon = "🌮", Description = "Tacos, burritos, and zesty dishes" },
            new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats and baked goods" },
            new() { Name = "Salads", Icon = "🥗", Description = "Fresh, healthy, and vibrant bowls" },
        ];
    }

    public List<Recipe> GetByCategory(string category)
        => _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id)
        => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAll() => _recipes;

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }
}

