    public List<RecipeCategory> GetCategories()
    {
        return
        [
            new() { Name = "Italian", Icon = "🍝", Description = "Pasta, pizza, and Mediterranean classics" },
            new() { Name = "Indian", Icon = "🍛", Description = "Rich curries and aromatic spices" },
            new() { Name = "Asian", Icon = "🍜", Description = "Stir-fries, noodles, and bold flavors" },
            new() { Name = "Mexican", Icon = "🌮", Description = "Tacos, burritos, and zesty dishes" },
            new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats and baked goods" },
            new() { Name = "Salads", Icon = "🥗", Description = "Fresh, healthy, and vibrant bowls" },
        ];
    }

    public List<Recipe> GetByCategory(string category)
        => _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id)
        => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAll() => _recipes;

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }
}

