                        <p class="card-text">@recipe.Description</p>
                        <div class="text-warning mb-2">
                            @for (int i = 1; i <= 5; i++)
                            {
                                <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                            }
                            <small class="text-muted ms-1">(@recipe.AverageRating.ToString("F1"))</small>
                        </div>
                        <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<div class="mt-4">
    <a href="/" class="btn btn-outline-secondary">← Back to Categories</a>
</div>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] public required RecipeService RecipeService { get; set; }

    private List<Recipe> recipes = [];
    private string categoryIcon = "";

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(Category);
        var cat = RecipeService.GetCategories()
            .FirstOrDefault(c => c.Name.Equals(Category, StringComparison.OrdinalIgnoreCase));
        categoryIcon = cat?.Icon ?? "📖";
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category">@recipe.Category</a></li>
