@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h2>📝 Submit Your Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community!</p>
<hr />

@if (submitted)
{
    <div class="alert alert-success">
        <h5>🎉 Recipe submitted!</h5>
        <p>Your recipe "<strong>@title</strong>" has been added. <a href="recipe/@newId">View it here</a>.</p>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-bold">Recipe Title</label>
                    <InputText @bind-Value="title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-bold">Category</label>
                    <InputSelect @bind-Value="category" class="form-select">
                        <option value="">-- Select a category --</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat.Name">@cat.Icon @cat.Name</option>
                        }
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label class="form-label fw-bold">Description</label>
                    <InputTextArea @bind-Value="description" class="form-control" rows="2"
                        placeholder="A short description of your recipe" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-bold">Ingredients</label>
                    <InputTextArea @bind-Value="ingredients" class="form-control" rows="5"
                        placeholder="One ingredient per line&#10;e.g.&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                    <small class="text-muted">Enter one ingredient per line.</small>
                </div>

                <div class="mb-3">
                    <label class="form-label fw-bold">Steps</label>
                    <InputTextArea @bind-Value="steps" class="form-control" rows="6"
                        placeholder="One step per line&#10;e.g.&#10;Preheat oven to 350°F.&#10;Mix dry ingredients together.&#10;Add wet ingredients and stir." />
                    <small class="text-muted">Enter one step per line.</small>
                </div>

                @if (!string.IsNullOrEmpty(error))
                {
                    <div class="alert alert-danger">@error</div>
                }

                <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
                <a href="/" class="btn btn-outline-secondary btn-lg ms-2">Cancel</a>
            </div>
        </div>
    </EditForm>
}

@code {
    [Inject] public required RecipeService RecipeService { get; set; }

    private string title = "";
    private string category = "";
    private string description = "";
    private string ingredients = "";
    private string steps = "";
    private string error = "";
    private bool submitted;
    private int newId;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category)
            || string.IsNullOrWhiteSpace(ingredients) || string.IsNullOrWhiteSpace(steps))
        {
            error = "Please fill in all required fields (title, category, ingredients, and steps).";
            return;
        }

        var recipe = new Recipe
        {
            Title = title.Trim(),
            Category = category,
            Description = description.Trim(),
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeService.AddRecipe(recipe);
        newId = recipe.Id;
        submitted = true;
        error = "";
    }

    private void Reset()
    {
        title = category = description = ingredients = steps = error = "";
        submitted = false;
    }
}

@using RecipeCommunity.Services

<div class="my-3">
    <span class="me-2 fw-bold">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star-rating @(star <= (userRating ?? hoverRating) ? "active" : "")"
              role="button"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0">
            @(star <= (userRating ?? hoverRating) ? "★" : "☆")
        </span>
    }

    @if (userRating.HasValue)
    {
        <span class="ms-2 text-success">✓ You rated @userRating stars</span>
    }

    @if (averageRating > 0)
    {
        <span class="ms-3 text-muted">
            Average: @averageRating.ToString("F1") / 5 (@totalRatings ratings)
        </span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private int? userRating;
    private int hoverRating;
    private double averageRating;
    private int totalRatings;

    protected override void OnParametersSet() => RefreshStats();

    private void Rate(int stars)
    {
        userRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        RefreshStats();
    }

    private void RefreshStats()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            averageRating = recipe.AverageRating;
            totalRatings = recipe.TotalRatings;
        }
    }
}

